        c = _c;
    }

    function run(
        uint256 tokenId,
        uint256 tokenWeight,
        uint256[] calldata proof,
        bool[] calldata flags,
        uint256 virtualBaseTokenReserves,
        uint256 virtualNftReserves,
        uint256 changeFee,
        uint256 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        require(virtualBaseTokenReserves > 0 && virtualBaseTokenReserves <= type(uint128).max, "vbr range");
        require(virtualNftReserves > 0 && virtualNftReserves <= type(uint128).max, "vnr range");
        require(changeFee <= type(uint56).max, "changeFee range");
        require(feeRate <= 5000, "feeRate range");

        c.initialize(
            address(0),
            address(0),
            uint128(virtualBaseTokenReserves),
            uint128(virtualNftReserves),
            uint56(changeFee),
            uint16(feeRate),
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;
        uint256[] memory tokenWeights = new uint256[](1);
        tokenWeights[0] = tokenWeight;

        MerkleMultiProof memory p;
        p.proof = proof;
        p.flags = flags;

        IStolenNftOracle.Message[] memory stolenNftProofs = new IStolenNftOracle.Message[](0);

        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        (bool success, uint256 netOutput, uint256 fee, uint256 protocolFee) =
            address(c).call(abi.encodeWithSignature(
                "sell(uint256[],uint256[],(bytes32[],bool[]),(bytes32,bytes,uint256,bytes)[])",
                tokenIds,
                tokenWeights,
                p,
                stolenNftProofs
            ));

        assert(!success || c.virtualNftReserves() == beforeVirtualNftReserves + uint128(tokenIds.length * 1e18));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 tokenId,
        uint256 nftCount,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 initialChangeFee,
        uint16 initialFeeRate
    ) public {
        require(virtualBaseTokenReserves > 0, "vbr > 0");
        require(virtualNftReserves > 0, "vnr > 0");
        require(nftCount > 0 && nftCount <= 100, "nftCount");
        require(initialFeeRate <= 5000, "feeRate");

        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReserves,
            virtualNftReserves,
            initialChangeFee,
            initialFeeRate,
            bytes32(0),
            false,
            false
        );

        uint256[] memory tokenIds = new uint256[](nftCount);
        uint256[] memory tokenWeights = new uint256[](nftCount);
        for (uint256 i = 0; i < nftCount; i++) {
            tokenIds[i] = tokenId + i;
            tokenWeights[i] = 1e18;
        }

        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        IStolenNftOracle.Message[] memory stolenNftProofs = new IStolenNftOracle.Message[](0);

        uint256 weightSum = nftCount * 1e18;

        (uint256 expectedNetOutput, uint256 expectedFee, uint256 expectedProtocolFee) =
            c.sellQuote(weightSum);

        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        (bool success, uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            address(c).call(abi.encodeWithSignature(
                "sell(uint256[],uint256[],(bytes32[],bool[]),(bytes32,bytes,uint256,bytes)[])",
                tokenIds,
                tokenWeights,
                proof,
                stolenNftProofs
            ));

        assert(
            !success ||
            (netOutputAmount == expectedNetOutput &&
             feeAmount == expectedFee &&
             protocolFeeAmount == expectedProtocolFee &&
             c.virtualNftReserves() == beforeVirtualNftReserves + uint128(weightSum) &&
             c.virtualBaseTokenReserves() == beforeVirtualBaseTokenReserves - uint128(netOutputAmount + protocolFeeAmount + feeAmount) &&
             address(this).balance == netOutputAmount)
        );
    }

    receive() external payable {}
}

