        uint256 tokenId,
        uint256 nftCount,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 initialChangeFee,
        uint16 initialFeeRate
    ) public payable {
        require(virtualBaseTokenReserves > 0, "vbr > 0");
        require(virtualNftReserves > 0, "vnr > 0");
        require(nftCount > 0 && nftCount <= 50, "nftCount");
        require(initialFeeRate <= 5000, "feeRate");
        require(virtualNftReserves > nftCount * 1e18, "vbr enough");

        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReserves,
            virtualNftReserves,
            initialChangeFee,
            initialFeeRate,
            bytes32(0),
            false,
            false
        );

        uint256[] memory tokenIds = new uint256[](nftCount);
        uint256[] memory tokenWeights = new uint256[](nftCount);
        for (uint256 i = 0; i < nftCount; i++) {
            tokenIds[i] = tokenId + i;
            tokenWeights[i] = 1e18;
        }

        c.deposit{value: 0}(tokenIds, 0);

        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        IStolenNftOracle.Message[] memory stolenNftProofs = new IStolenNftOracle.Message[](0);

        uint256 weightSum = nftCount * 1e18;

        (uint256 expectedNetOutput, uint256 expectedFee, uint256 expectedProtocolFee) =
            c.sellQuote(weightSum);

        uint256 expectedBaseDecrease = expectedNetOutput + expectedFee + expectedProtocolFee;
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        require(address(c).balance >= expectedNetOutput, "pool has enough ETH");

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.sell(tokenIds, tokenWeights, proof, stolenNftProofs);

        assert(
            netOutputAmount == expectedNetOutput &&
            feeAmount == expectedFee &&
            protocolFeeAmount == expectedProtocolFee &&
            c.virtualNftReserves() == beforeVirtualNftReserves + uint128(weightSum) &&
            c.virtualBaseTokenReserves() == beforeVirtualBaseTokenReserves - uint128(expectedBaseDecrease)
        );
    }

    receive() external payable {}
}

